## kms.tf
```hcl
resource "aws_kms_key" "invoice" {
  description             = "CMK mã hoá hoá đơn PDF (PII) - ${var.env}"
  enable_key_rotation     = true          # xoay vòng hằng năm, bắt buộc theo secrets-management
  rotation_period_in_days = 365
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "invoice" {
  name          = "alias/${var.project}-invoice-${var.env}"
  target_key_id = aws_kms_key.invoice.key_id
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms" {
  statement {
    sid     = "AccountAdminViaIAM"
    effect  = "Allow"
    actions = ["kms:*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    resources = ["*"]
  }

  statement {
    sid    = "ServiceUseOnlyViaS3"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.payment_service_invoice_rw.arn]
    }
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

data "aws_region" "current" {}
```

## s3.tf
```hcl
resource "aws_s3_bucket" "invoice" {
  bucket        = var.bucket_name
  force_destroy = false # không bao giờ xoá kèm object
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true # ghi đè bằng biến ở dev qua module wrapper nếu cần; prod luôn true
  }
}

resource "aws_s3_bucket_public_access_block" "invoice" {
  bucket                  = aws_s3_bucket.invoice.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "invoice" {
  bucket = aws_s3_bucket.invoice.id
  rule {
    object_ownership = "BucketOwnerEnforced" # vô hiệu hoá ACL hoàn toàn
  }
}

resource "aws_s3_bucket_versioning" "invoice" {
  bucket = aws_s3_bucket.invoice.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "invoice" {
  bucket = aws_s3_bucket.invoice.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.invoice.arn
    }
    bucket_key_enabled = true # giảm số lời gọi KMS => giảm chi phí
  }
}

resource "aws_s3_bucket_logging" "invoice" {
  bucket        = aws_s3_bucket.invoice.id
  target_bucket = var.log_bucket_name
  target_prefix = "s3-access/${var.bucket_name}/"
}

resource "aws_s3_bucket_lifecycle_configuration" "invoice" {
  bucket = aws_s3_bucket.invoice.id

  rule {
    id     = "abort-incomplete-uploads"
    status = "Enabled"
    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  rule {
    id     = "invoice-retention"
    status = "Enabled"
    filter {
      prefix = local.invoice_prefix
    }
    transition {
      days          = var.transition_ia_days
      storage_class = "STANDARD_IA"
    }
    expiration {
      days = var.retention_days
    }
    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }
  }
}

resource "aws_s3_bucket_policy" "invoice" {
  bucket = aws_s3_bucket.invoice.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.invoice]
}

data "aws_iam_policy_document" "bucket" {
  # 1) Chặn mọi principal ngoài allowlist -> đáp ứng acceptance "Không ai ngoài dịch vụ đọc được"
  statement {
    sid     = "DenyEveryoneExceptAllowlist"
    effect  = "Deny"
    actions = ["s3:*"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    resources = [
      aws_s3_bucket.invoice.arn,
      "${aws_s3_bucket.invoice.arn}/*",
    ]
    condition {
      test     = "ArnNotLike"
      variable = "aws:PrincipalArn"
      values   = local.allowed_principal_arns
    }
  }

  # 2) Chỉ TLS >= 1.2
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    resources = [
      aws_s3_bucket.invoice.arn,
      "${aws_s3_bucket.invoice.arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "DenyOldTls"
    effect  = "Deny"
    actions = ["s3:*"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    resources = [
      aws_s3_bucket.invoice.arn,
      "${aws_s3_bucket.invoice.arn}/*",
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  # 3) Không cho ghi object không mã hoá bằng đúng CMK
  statement {
    sid     = "DenyWrongEncryption"
    effect  = "Deny"
    actions = ["s3:PutObject"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    resources = ["${aws_s3_bucket.invoice.arn}/*"]
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid     = "DenyWrongKmsKey"
    effect  = "Deny"
    actions = ["s3:PutObject"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    resources = ["${aws_s3_bucket.invoice.arn}/*"]
    condition {
      test     = "StringNotEqualsIfExists"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.invoice.arn]
    }
  }
}
```

## iam.tf — least privilege cho payment-service (IRSA, không khoá dài hạn)
```hcl
resource "aws_iam_role" "payment_service_invoice_rw" {
  name               = "${var.project}-payment-service-invoice-rw-${var.env}"
  assume_role_policy = data.aws_iam_policy_document.assume_irsa.json
  max_session_duration = 3600
  tags               = local.common_tags
}

data "aws_iam_policy_document" "assume_irsa" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_namespace}:${var.service_account_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "invoice_rw" {
  statement {
    sid     = "ListOnlyInvoicePrefix"
    effect  = "Allow"
    actions = ["s3:ListBucket"]
    resources = [aws_s3_bucket.invoice.arn]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${local.invoice_prefix}*"]
    }
  }

  statement {
    sid    = "ReadWriteInvoiceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]
    # KHÔNG có s3:DeleteObject: xoá do lifecycle đảm nhiệm, dịch vụ không được xoá hoá đơn
    resources = ["${aws_s3_bucket.invoice.arn}/${local.invoice_prefix}*"]
  }

  statement {
    sid    = "UseCmkViaS3Only"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.invoice.arn]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "invoice_rw" {
  name   = "${var.project}-invoice-rw-${var.env}"
  policy = data.aws_iam_policy_document.invoice_rw.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "invoice_rw" {
  role       = aws_iam_role.payment_service_invoice_rw.name
  policy_arn = aws_iam_policy.invoice_rw.arn
}
```

## observability.tf — CloudTrail data events + alarm (chi tiết ngưỡng ở RB-21)
```hcl
resource "aws_cloudtrail_event_data_store" "placeholder" {
  count = 0 # dùng trail tổ chức sẵn có; chỉ bổ sung advanced event selector cho bucket này
}

# Đăng ký data events cho bucket vào trail tổ chức (module ngoài quản lý trail).
# Xem terraform/envs/invoice-store.tfvars.md để biết biến trail_name.

resource "aws_cloudwatch_metric_alarm" "access_denied" {
  alarm_name          = "invoice-store-access-denied-${var.env}"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  threshold           = 5
  period              = 300
  namespace           = "AWS/S3"
  metric_name         = "4xxErrors"
  statistic           = "Sum"
  dimensions = {
    BucketName = aws_s3_bucket.invoice.id
    FilterId   = "EntireBucket"
  }
  alarm_description = "RB-21 §4.3 - nghi vấn truy cập ngoài allowlist"
  tags              = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "kms_key_state" {
  alarm_name          = "invoice-store-kms-key-disabled-${var.env}"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
