# Trạng thái: CHƯA chạy trong phiên tạo file (không có tool). Pipeline phải chạy và đính kết quả.

```rego
package main

import future.keywords.in

# ---------- 1. Không destroy tài nguyên chứa dữ liệu ----------
data_resource_types := {"aws_s3_bucket", "aws_kms_key", "aws_db_instance", "aws_rds_cluster"}

deny contains msg if {
  rc := input.resource_changes[_]
  rc.type in data_resource_types
  "delete" in rc.change.actions
  msg := sprintf("CHẶN: plan xoá tài nguyên chứa dữ liệu %s. Cần backup + 2 người duyệt (RB-21 §6).", [rc.address])
}

# ---------- 2. Bucket không được public ----------
deny contains msg if {
  rc := input.resource_changes[_]
  rc.type == "aws_s3_bucket_public_access_block"
  after := rc.change.after
  some flag in ["block_public_acls", "block_public_policy", "ignore_public_acls", "restrict_public_buckets"]
  after[flag] != true
  msg := sprintf("CHẶN: %s có %s != true. Block Public Access phải bật đủ 4 cờ.", [rc.address, flag])
}

# Mọi aws_s3_bucket phải có public access block đi kèm
deny contains msg if {
  rc := input.resource_changes[_]
  rc.type == "aws_s3_bucket"
  not has_pab(rc.change.after.bucket)
  msg := sprintf("CHẶN: bucket %s thiếu aws_s3_bucket_public_access_block.", [rc.address])
}

has_pab(name) if {
  some other in input.resource_changes
  other.type == "aws_s3_bucket_public_access_block"
  other.change.after.bucket == name
}

# ---------- 3. Mã hoá at-rest bằng KMS (threat-model v1: hoá đơn là PII) ----------
deny contains msg if {
  rc := input.resource_changes[_]
  rc.type == "aws_s3_bucket_server_side_encryption_configuration"
  rule := rc.change.after.rule[_]
  d := rule.apply_server_side_encryption_by_default[_]
  d.sse_algorithm != "aws:kms"
  msg := sprintf("CHẶN: %s dùng %s. Dữ liệu PII phải mã hoá bằng aws:kms với CMK riêng.", [rc.address, d.sse_algorithm])
}

deny contains msg if {
  rc := input.resource_changes[_]
  rc.type == "aws_kms_key"
  rc.change.after.enable_key_rotation != true
  msg := sprintf("CHẶN: %s không bật xoay vòng khoá.", [rc.address])
}

# ---------- 4. Không IAM wildcard ----------
deny contains msg if {
  rc := input.resource_changes[_]
  rc.type in {"aws_iam_policy", "aws_iam_role_policy"}
  doc := json.unmarshal(rc.change.after.policy)
  st := doc.Statement[_]
  st.Effect == "Allow"
  wildcard_action(st.Action)
  msg := sprintf("CHẶN: %s có Allow với Action wildcard.", [rc.address])
}

deny contains msg if {
  rc := input.resource_changes[_]
  rc.type in {"aws_iam_policy", "aws_iam_role_policy"}
  doc := json.unmarshal(rc.change.after.policy)
  st := doc.Statement[_]
  st.Effect == "Allow"
  st.Resource == "*"
  not st.Condition
  msg := sprintf("CHẶN: %s có Allow trên Resource \"*\" mà không có Condition thu hẹp.", [rc.address])
}

wildcard_action(a) if { a == "*" }
wildcard_action(a) if { is_array(a); "*" in a }
wildcard_action(a) if { is_array(a); endswith(a[_], ":*") }
wildcard_action(a) if { is_string(a); endswith(a, ":*") }

# ---------- 5. Tag bắt buộc ----------
required_tags := {"project", "env", "owner", "cost-center"}
taggable := {"aws_s3_bucket", "aws_kms_key", "aws_iam_role", "aws_iam_policy"}

deny contains msg if {
  rc := input.resource_changes[_]
  rc.type in taggable
  not "delete" in rc.change.actions
  some t in required_tags
  not rc.change.after.tags[t]
  msg := sprintf("CHẶN: %s thiếu tag bắt buộc '%s'.", [rc.address, t])
}

# ---------- 6. Không mở cổng quản trị ra Internet (dùng chung toàn repo) ----------
deny contains msg if {
  rc := input.resource_changes[_]
  rc.type == "aws_security_group_rule"
  rc.change.after.type == "ingress"
  "0.0.0.0/0" in rc.change.after.cidr_blocks
  rc.change.after.from_port <= 22
  rc.change.after.to_port >= 22
  msg := sprintf("CHẶN: %s mở SSH ra Internet.", [rc.address])
}

# ---------- 7. Không secret dạng chuỗi trong biến/plan ----------
deny contains msg if {
  rc := input.resource_changes[_]
  val := walk_values(rc.change.after)
  regex.match(`(?i)(aws_secret_access_key|password\s*=|-----BEGIN [A-Z ]*PRIVATE KEY-----)`, val)
  msg := sprintf("CHẶN: nghi ngờ secret trong plan tại %s. Dùng kho bí mật, không đưa vào IaC.", [rc.address])
}

walk_values(obj) := v if {
  walk(obj, [_, v])
  is_string(v)
}
